 for(const r of list.requests){
  const k='REQ:'+r.clinic+':'+r.id,current=get_(k);if(!current)continue;
  const m=members.get(JSON.stringify([r.clinic,email_(r.email),r.role]));
  const deletedClinic=get_('CLINIC:'+r.clinic)?.deleted;
  if(current.status==='Archived')continue;
  if(deletedClinic||(current.status==='Approved'&&(!m||(current.accountUid&&current.accountUid!==m.uid)||(!current.accountUid&&m.activated&&current.resolved&&Date.parse(m.activated)>Date.parse(current.resolved))))){current.previousStatus=current.status;current.status='Archived';current.archivedAt=new Date().toISOString();current.reason=deletedClinic?'Clinic removed':'Linked account no longer exists';}
