  const admins=others.filter(u=>u.role==='Admin');check_(admins.length>0,'Cannot delete the last administrator.');
  if(m.enabled&&!m.pending&&m.keyHash&&validLicense_(m))check_(admins.some(u=>{const a=get_(memberKey_(c,u.email));return a&&a.enabled&&!a.pending&&a.keyHash&&validLicense_(a);}), 'Cannot delete the last eligible administrator. Activate another administrator first.');
 }
