  const ss=SpreadsheetApp.openById(reg.sheetId),r=read_(ss,reg),d=r.data.dentists.find(x=>x.id===m.did);
  if(d&&!d.deleted){d.deleted=true;r.data.log.unshift({time:new Date().toISOString(),msg:'Dentist profile archived by provider; historical records retained',actor:'management',role:'Admin'});write_(ss,r.data,1-r.slot,r.revision+1,reg,r.snapshot);}
 }
 const at=new Date().toISOString(),sessions=m.sessions||[];
