function nativeRanks_(entries,old){const ranks=new Map(old.map(r=>[r.key,r.rank])),retained=entries.filter(e=>ranks.has(e.key));let valid=retained.every((r,i)=>!i||ranks.get(retained[i-1].key)<ranks.get(r.key));if(valid){for(let i=0;i<entries.length;){if(ranks.has(entries[i].key)){i++;continue;}let j=i;while(j<entries.length&&!ranks.has(entries[j].key))j++;const left=i?ranks.get(entries[i-1].key):null,right=j<entries.length?ranks.get(entries[j].key):null,step=left===null||right===null?1024:(right-left)/(j-i+1);for(let n=i;n<j;n++){const rank=left!==null?left+step*(n-i+1):right!==null?right-step*(j-n):1024*(n+1);if(!Number.isFinite(rank)||(n>i&&rank<=ranks.get(entries[n-1].key))||(left!==null&&rank<=left)||(right!==null&&rank>=right))valid=false;ranks.set(entries[n].key,rank);}i=j;}}if(!valid)entries.forEach((e,i)=>ranks.set(e.key,1024*(i+1)));return ranks;}
function nativePlanTable_(name,entries,raw,grid,requests){const old=nativeReadTable_(raw,name),headers=old.headers.slice(),fields=new Set(headers),prepared=entries.map(e=>({...e,...nativeFlat_(e.value)}));for(const e of prepared)for(const k of Object.keys(e.cells))if(!fields.has(k)){check_(!NATIVE_META_.includes(k),'Reserved field name.');fields.add(k);headers.push(k);}check_(headers.length<=18278,'Too many spreadsheet columns.');const oldByKey=new Map(old.rows.map(r=>[r.key,r])),nextKeys=new Set(entries.map(e=>e.key)),free=old.rows.filter(r=>!nextKeys.has(r.key)).map(r=>r.row);for(let i=1;i<raw.length;i++)if(!raw[i]?.[0])free.push(i);free.sort((a,b)=>a-b);let end=Math.max(1,raw.length),freeIndex=0;const ranks=nativeRanks_(entries,old.rows),writes=[];for(const e of prepared){const pos=oldByKey.get(e.key)?.row??(freeIndex<free.length?free[freeIndex++]:end++);const row=[e.key,ranks.get(e.key),e.parent,e.meta,...headers.slice(4).map(h=>e.cells[h]??'')];writes.push({pos,row});}for(;freeIndex<free.length;freeIndex++)writes.push({pos:free[freeIndex],row:[]});const maxRow=writes.reduce((m,r)=>Math.max(m,r.pos+1),1);if(headers.length>grid.gridProperties.columnCount)requests.push({appendDimension:{sheetId:grid.sheetId,dimension:'COLUMNS',length:headers.length-grid.gridProperties.columnCount}});if(maxRow>grid.gridProperties.rowCount)requests.push({appendDimension:{sheetId:grid.sheetId,dimension:'ROWS',length:maxRow-grid.gridProperties.rowCount}});if(headers.length>old.headers.length)nativeUpdate_(requests,grid.sheetId,0,old.headers.length,headers.slice(old.headers.length));for(const {pos,row} of writes){const prev=nativeTrimRow_(raw[pos],headers.length),next=nativeTrimRow_(row,headers.length);let i=0;while(i<next.length){while(i<next.length&&prev[i]===next[i])i++;if(i===next.length)break;let j=i+1;while(j<next.length&&prev[j]!==next[j])j++;nativeUpdate_(requests,grid.sheetId,pos,i,next.slice(i,j));i=j;}}return headers;}
function nativeCommit_(s,tables,revision,snapshot){const requests=[];for(const name of NATIVE_NAMES_)nativePlanTable_(name,tables[name],snapshot.raw[name],snapshot.grids[name],requests);nativeUpdate_(requests,snapshot.grids._Commit.sheetId,0,0,[revision,2]);Sheets.Spreadsheets.batchUpdate({requests},s.getId());}
function nativeMigration_(s,data,revision,reg,snapshot){check_(snapshot.commit[1]!==2,'Already tabular.');check_(!snapshot.grids.Attachments,'Attachments tab already exists. Rename unrelated tab before migration.');const tables=nativeTables_(data),requests=[],ids=new Set(Object.values(snapshot.grids).map(x=>x.sheetId));let id=1;function nextId(){while(ids.has(id))id++;ids.add(id);return id++;}const names=['_Commit',...NATIVE_NAMES_];for(const name of names){if(snapshot.grids[name]){check_(!snapshot.grids['_Legacy_'+name],'Legacy backup tab already exists. Contact support.');requests.push({updateSheetProperties:{properties:{sheetId:snapshot.grids[name].sheetId,title:'_Legacy_'+name},fields:'title'}});}}const decoded={};for(const name of names){const sheetId=nextId();let rows;if(name==='_Commit'){rows=[[revision,2]];}else{const headers=[...NATIVE_META_,...(NATIVE_FIELDS_[name]||[])],fields=new Set(headers),entries=tables[name].map(e=>({...e,...nativeFlat_(e.value)}));for(const e of entries)for(const k of Object.keys(e.cells))if(!fields.has(k)){fields.add(k);headers.push(k);}rows=[headers,...entries.map((e,i)=>[e.key,1024*(i+1),e.parent,e.meta,...headers.slice(4).map(h=>e.cells[h]??'')])];decoded[name]=nativeReadTable_(rows,name).rows;}const rowCount=Math.max(100,rows.length+20),columnCount=Math.max(10,rows[0].length);check_(columnCount<=18278,'Too many columns.');requests.push({addSheet:{properties:{sheetId,title:name,gridProperties:{rowCount,columnCount,frozenRowCount:name==='_Commit'?0:1}}}});requests.push({updateCells:{start:{sheetId,rowIndex:0,columnIndex:0},rows:rows.map(r=>({values:r.map(nativeCell_)})),fields:'userEnteredValue'}});if(name!=='_Commit'){for(const [a,b] of (['Treatments','Payments','ProgressNotes','TreatmentPlans','Attachments'].includes(name)?[[0,2],[3,4]]:[[0,4]]))requests.push({updateDimensionProperties:{range:{sheetId,dimension:'COLUMNS',startIndex:a,endIndex:b},properties:{hiddenByUser:true},fields:'hiddenByUser'}});requests.push({repeatCell:{range:{sheetId,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:{red:.89,green:.94,blue:.90},textFormat:{bold:true}}},fields:'userEnteredFormat'}});}}for(const name of names)if(snapshot.grids[name])requests.push({updateSheetProperties:{properties:{sheetId:snapshot.grids[name].sheetId,hidden:true},fields:'hidden'}});const restored=nativeDecode_(decoded,reg);check_(equal_(data,restored),'Migration round-trip mismatch. No changes written.');Sheets.Spreadsheets.batchUpdate({requests},s.getId());return {revision,layout:'Tabular V2',backup:'_Legacy_* tabs retained'};}
function ownerMigrate(c){ownerGuard_();return lock_(()=>{check_(clinicKey_(c)&&!get_('REMOTE:'+c),'Run migration in the clinic-owned dashboard.');const reg=get_('CLINIC:'+c);check_(reg,'Unknown clinic.');const s=SpreadsheetApp.openById(reg.sheetId),r=read_(s,reg);if(r.slot===2)return {revision:r.revision,layout:'Tabular V2',already:true};return nativeMigration_(s,r.data,r.revision+1,reg,r.snapshot);});}

function commitMeta_(reg){const r=Sheets.Spreadsheets.Values.get(reg.sheetId,"'_Commit'!A1:B1",{valueRenderOption:'UNFORMATTED_VALUE'}).values?.[0];check_(r&&Number.isInteger(r[0])&&[0,1,2].includes(r[1]),'Database connection or metadata unavailable.');return r;}
function recordPerf_(c,ok,ms){try{const k='PERF:'+c,p=get_(k)||{count:0,totalMs:0,failed:0};if(ok){p.count++;p.totalMs+=ms;p.lastMs=ms;p.lastAt=new Date().toISOString();}else{p.failed++;p.lastFailedAt=new Date().toISOString();}put_(k,p);}catch(_){/* monitoring must not invalidate a confirmed commit */}}

/* V28.5: account roster and archive lifecycle. No clinical data is deleted. */
function activeDentistIds_(c){const all=props_().getProperties(),ids=new Set();for(const [k,v] of Object.entries(all)){if(!k.startsWith('MEMBER:'+c+':'))continue;const m=JSON.parse(v);if(!m.deleted&&m.role==='Dentist'&&m.did&&m.enabled&&!m.pending&&m.keyHash&&validLicense_(m))ids.add(m.did);}return [...ids].sort();}
function validateRosterAssignments_(next,previous,a){const eligible=new Set(activeDentistIds_(a.clinic)),old=map_(previous.visits);for(const v of next.visits){const before=old.get(v.id);if(!before||before.did!==v.did||(!done_(before)&&!done_(v)&&v.status!=='Cancelled'&&(before.date!==v.date||before.time!==v.time||before.status==='Cancelled')))check_(eligible.has(v.did),'Dentist account is not active. Refresh and choose an activated dentist.');}}
function archiveUnlinkedDentist_(c,reg,t){check_(id_(t.did),'Invalid dentist ID.');check_(!localList_(c).users.some(u=>u.role==='Dentist'&&u.did===t.did),'Dentist is linked to an account. Manage that account instead.');const ss=SpreadsheetApp.openById(reg.sheetId),r=read_(ss,reg),d=r.data.dentists.find(x=>x.id===t.did);check_(d,'Unknown dentist profile.');if(!d.deleted){d.deleted=true;r.data.log.unshift({time:new Date().toISOString(),msg:'Unlinked dentist profile archived by provider',actor:'management',role:'Admin'});write_(ss,r.data,1-r.slot,r.revision+1,reg,r.snapshot);auditOwner_(c,'Unlinked dentist archived',t.did);}return {ok:true};}
function deleteClinicLocal_(c,reg,t){check_(t.confirmClinic===c,'Type the clinic ID to confirm.');const at=reg.deletedAt||new Date().toISOString();reg.enabled=false;reg.deleted=true;reg.deletedAt=at;put_('CLINIC:'+c,reg); // blocks all sessions immediately; ID stays reserved
 const all=props_().getProperties();for(const [k,v] of Object.entries(all)){if(k.startsWith('MEMBER:'+c+':')){const m=JSON.parse(v);if(!m.deleted){const sessions=m.sessions||[];put_(k,{...archiveSummary_(m),deleted:true,deletedAt:at,enabled:false,pending:false,keyHash:'',epoch:secret_(),sessions:[]});for(const h of sessions)props_().deleteProperty('S:'+h);}}else if(k.startsWith('REQ:'+c+':')){const r=JSON.parse(v);if(r.status!=='Archived'){r.previousStatus=r.status;r.status='Archived';r.archivedAt=at;r.reason='Clinic removed';put_(k,r);}}}auditOwner_(c,'Clinic registration removed; storage retained','');return {ok:true,deleted:true,clinic:c};}
function voidArchivedBilling_(c,t){check_(typeof t.uid==='string'&&id_(t.uid),'Invalid account ID.');const reason=String(t.reason||'').trim();check_(reason&&reason.length<=200,'Enter a reason (maximum 200 characters).');const archived='ARCHIVED:'+c+':'+t.uid,member=memberKey_(c,t.email),old=get_(archived),m=get_(member);const key=old?archived:member,record=old||m;check_(record&&record.clinic===c&&memberUid_(record)===t.uid&&(old||m.deleted||get_('CLINIC:'+c)?.deleted),'Archived billing record not found.');if(!record.voided){record.voided=true;record.voidedAt=new Date().toISOString();record.voidReason=reason;put_(key,record);auditOwner_(c,'Archived billing voided: '+reason,record.email);}return {ok:true};}
